package com.utegear.repository;
import com.utegear.entity.Category; import java.util.List; import java.util.Optional; import org.springframework.data.jpa.repository.JpaRepository;
public interface CategoryRepository extends JpaRepository<Category,Long>{ boolean existsByNameIgnoreCase(String name); boolean existsByNameIgnoreCaseAndIdNot(String name,Long id); boolean existsBySlug(String slug); boolean existsBySlugAndIdNot(String slug,Long id); Optional<Category> findBySlug(String slug); Optional<Category> findBySlugAndActiveTrue(String slug); List<Category> findByActiveTrueOrderBySortOrderAscNameAsc(); List<Category> findAllByOrderBySortOrderAscNameAsc(); }
